{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Carebastine, which contains the same 4-(1-carboxy-1-methylethyl)phenyl zwitterionic acid moiety as the query, exists as a zwitterion at physiological pH and accordingly does not cross the blood-brain barrier; this directly transfers the acid/zwitterion CNS-penetration liability to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "In vivo, carebastine required 83.9 mg/kg to achieve 50% inhibition of central H1 binding, demonstrating poor brain penetration for a zwitterionic acid analogue; the query shares the same acid and a basic piperidine, so similar poor CNS access is expected.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Fexofenadine, another zwitterionic α,α-dimethylphenylacetic acid with a basic piperidine, is experimentally confirmed not to cross the BBB; this independent example reinforces that the query's acid/zwitterion pharmacophore is a strong CNS-penetration liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The same benzimidazole-N-ethoxyethyl core without the acid (emedastine) showed a low brain/plasma radioactivity ratio of 1/17, indicating that even the core alone is not strongly brain-penetrant; adding the ionized acid side chain is expected to further reduce CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "A close benzimidazole-piperidine analogue (9n) with the same N-ethoxyethyl benzimidazole core achieved a B/Pb ratio of 2.6, showing the core can be CNS-penetrant when the piperidine N-substituent is lipophilic; however, the query replaces that substituent with an ionized phenethyl-carboxylic acid, so this favourable core evidence does not overcome the zwitterion liability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Another benzimidazole-piperidine analogue (9q) had a B/Pb ratio of 2.7, supporting CNS access for the scaffold; but it lacks the carboxylic acid/zwitterion that dominates the query's permeability profile.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a zwitterionic benzimidazole-piperidine bearing the same α,α-dimethylphenylacetic acid moiety as carebastine and fexofenadine, both of which are experimentally confirmed not to cross the BBB. Although the benzimidazole-piperidine core can be CNS-penetrant when substituted with lipophilic groups (B/Pb 2.6), the ionized carboxylic acid/zwitterion is a dominant permeability liability and no evidence shows active uptake for this scaffold. Therefore, meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or transporter data for the exact query molecule.",
    "No evidence on whether the query is a substrate for an uptake transporter (e.g., OATP, LAT1) at the BBB.",
    "The closest core analogues lack the carboxylic acid, so the quantitative effect of the acid on this specific benzimidazole-piperidine scaffold is inferred from carebastine/fexofenadine rather than measured directly."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C13", "C21"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "benzimidazole-piperidine core analogues"
    },
    {
      "applicability": "high",
      "card_ids": ["C15", "C16", "C22"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "emedastine benzimidazole-ethoxyethyl core"
    },
    {
      "applicability": "high",
      "card_ids": ["C19", "C14", "C23", "C20", "C18"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "carebastine zwitterionic acid"
    },
    {
      "applicability": "high",
      "card_ids": ["C12", "C17"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "fexofenadine zwitterionic acid"
    }
  ],
  "revision_action": "strengthen"
}

